import 'package:flutter/material.dart';
class TelaComprovante extends StatelessWidget { final String nome,local,situacao; final int total; const TelaComprovante({super.key,required this.nome,required this.local,required this.situacao,required this.total}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Comprovante')),body:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Objeto: $nome',style:const TextStyle(fontSize:20)),Text('Local: $local',style:const TextStyle(fontSize:20)),Text('Situação: $situacao',style:const TextStyle(fontSize:20)),Text('Total de registros: $total',style:const TextStyle(fontSize:20)),const SizedBox(height:30),FilledButton(onPressed:()=>Navigator.pop(context),child:const Text('Voltar'))]))); }
